with src as (
  select * from jsonb_to_recordset($bank$[{"source_key":"20001-1001-q001","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “อันตราย” ได้ถูกต้องที่สุด?","options":["เอกสารข้อมูลความปลอดภัยของสารเคมีที่อธิบายอันตราย การใช้ การเก็บ และการตอบโต้เหตุ","แหล่งหรือสภาวะที่มีศักยภาพก่อให้เกิดการบาดเจ็บ ความเจ็บป่วย หรือความเสียหาย","แนวคิดเลือกมาตรการจากการกำจัดอันตรายไปจนถึงอุปกรณ์ป้องกันส่วนบุคคล","แผนกำหนดบทบาท เส้นทาง การสื่อสาร และการตอบสนองเมื่อเกิดเหตุไม่ปกติ"],"correct_answer":"แหล่งหรือสภาวะที่มีศักยภาพก่อให้เกิดการบาดเจ็บ ความเจ็บป่วย หรือความเสียหาย","explanation":"อันตราย หมายถึง แหล่งหรือสภาวะที่มีศักยภาพก่อให้เกิดการบาดเจ็บ ความเจ็บป่วย หรือความเสียหาย","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q002","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “ความเสี่ยง” ได้ถูกต้องที่สุด?","options":["อุปกรณ์ที่สวมใส่เพื่อลดการสัมผัสอันตรายที่ยังเหลืออยู่","การแยก ปิดกั้น ระบาย หรือออกแบบอุปกรณ์เพื่อลดการสัมผัสอันตราย","การพิจารณาโอกาสเกิดเหตุร่วมกับความรุนแรงของผลกระทบ","ค่านิยมและพฤติกรรมร่วมที่ให้ความสำคัญกับความปลอดภัยในทุกระดับ"],"correct_answer":"การพิจารณาโอกาสเกิดเหตุร่วมกับความรุนแรงของผลกระทบ","explanation":"ความเสี่ยง หมายถึง การพิจารณาโอกาสเกิดเหตุร่วมกับความรุนแรงของผลกระทบ","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q003","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “การประเมินความเสี่ยง” ได้ถูกต้องที่สุด?","options":["การแยก ปิดกั้น ระบาย หรือออกแบบอุปกรณ์เพื่อลดการสัมผัสอันตราย","การออกแบบงาน เครื่องมือ และท่าทางให้เหมาะกับความสามารถของมนุษย์","เหตุการณ์ที่ยังไม่ทำให้เกิดความสูญเสียแต่มีศักยภาพก่ออันตรายได้","กระบวนการระบุอันตราย วิเคราะห์ความเสี่ยง และกำหนดมาตรการควบคุม"],"correct_answer":"กระบวนการระบุอันตราย วิเคราะห์ความเสี่ยง และกำหนดมาตรการควบคุม","explanation":"การประเมินความเสี่ยง หมายถึง กระบวนการระบุอันตราย วิเคราะห์ความเสี่ยง และกำหนดมาตรการควบคุม","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q004","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “ลำดับชั้นการควบคุม” ได้ถูกต้องที่สุด?","options":["แนวคิดเลือกมาตรการจากการกำจัดอันตรายไปจนถึงอุปกรณ์ป้องกันส่วนบุคคล","แผนกำหนดบทบาท เส้นทาง การสื่อสาร และการตอบสนองเมื่อเกิดเหตุไม่ปกติ","การแยกของเสียตามประเภทเพื่อจัดเก็บ นำกลับใช้ หรือกำจัดอย่างเหมาะสม","การออกแบบงาน เครื่องมือ และท่าทางให้เหมาะกับความสามารถของมนุษย์"],"correct_answer":"แนวคิดเลือกมาตรการจากการกำจัดอันตรายไปจนถึงอุปกรณ์ป้องกันส่วนบุคคล","explanation":"ลำดับชั้นการควบคุม หมายถึง แนวคิดเลือกมาตรการจากการกำจัดอันตรายไปจนถึงอุปกรณ์ป้องกันส่วนบุคคล","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q005","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “การควบคุมทางวิศวกรรม” ได้ถูกต้องที่สุด?","options":["ค่านิยมและพฤติกรรมร่วมที่ให้ความสำคัญกับความปลอดภัยในทุกระดับ","การแยก ปิดกั้น ระบาย หรือออกแบบอุปกรณ์เพื่อลดการสัมผัสอันตราย","กระบวนการระบุอันตราย วิเคราะห์ความเสี่ยง และกำหนดมาตรการควบคุม","การออกแบบงาน เครื่องมือ และท่าทางให้เหมาะกับความสามารถของมนุษย์"],"correct_answer":"การแยก ปิดกั้น ระบาย หรือออกแบบอุปกรณ์เพื่อลดการสัมผัสอันตราย","explanation":"การควบคุมทางวิศวกรรม หมายถึง การแยก ปิดกั้น ระบาย หรือออกแบบอุปกรณ์เพื่อลดการสัมผัสอันตราย","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q006","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “อุปกรณ์ป้องกันส่วนบุคคล” ได้ถูกต้องที่สุด?","options":["การพิจารณาโอกาสเกิดเหตุร่วมกับความรุนแรงของผลกระทบ","การแยก ปิดกั้น ระบาย หรือออกแบบอุปกรณ์เพื่อลดการสัมผัสอันตราย","อุปกรณ์ที่สวมใส่เพื่อลดการสัมผัสอันตรายที่ยังเหลืออยู่","ค่านิยมและพฤติกรรมร่วมที่ให้ความสำคัญกับความปลอดภัยในทุกระดับ"],"correct_answer":"อุปกรณ์ที่สวมใส่เพื่อลดการสัมผัสอันตรายที่ยังเหลืออยู่","explanation":"อุปกรณ์ป้องกันส่วนบุคคล หมายถึง อุปกรณ์ที่สวมใส่เพื่อลดการสัมผัสอันตรายที่ยังเหลืออยู่","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q007","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “การยศาสตร์” ได้ถูกต้องที่สุด?","options":["เหตุการณ์ที่ยังไม่ทำให้เกิดความสูญเสียแต่มีศักยภาพก่ออันตรายได้","กระบวนการระบุอันตราย วิเคราะห์ความเสี่ยง และกำหนดมาตรการควบคุม","การแยก ปิดกั้น ระบาย หรือออกแบบอุปกรณ์เพื่อลดการสัมผัสอันตราย","การออกแบบงาน เครื่องมือ และท่าทางให้เหมาะกับความสามารถของมนุษย์"],"correct_answer":"การออกแบบงาน เครื่องมือ และท่าทางให้เหมาะกับความสามารถของมนุษย์","explanation":"การยศาสตร์ หมายถึง การออกแบบงาน เครื่องมือ และท่าทางให้เหมาะกับความสามารถของมนุษย์","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q008","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “SDS” ได้ถูกต้องที่สุด?","options":["เอกสารข้อมูลความปลอดภัยของสารเคมีที่อธิบายอันตราย การใช้ การเก็บ และการตอบโต้เหตุ","แหล่งหรือสภาวะที่มีศักยภาพก่อให้เกิดการบาดเจ็บ ความเจ็บป่วย หรือความเสียหาย","แผนกำหนดบทบาท เส้นทาง การสื่อสาร และการตอบสนองเมื่อเกิดเหตุไม่ปกติ","การแยกของเสียตามประเภทเพื่อจัดเก็บ นำกลับใช้ หรือกำจัดอย่างเหมาะสม"],"correct_answer":"เอกสารข้อมูลความปลอดภัยของสารเคมีที่อธิบายอันตราย การใช้ การเก็บ และการตอบโต้เหตุ","explanation":"SDS หมายถึง เอกสารข้อมูลความปลอดภัยของสารเคมีที่อธิบายอันตราย การใช้ การเก็บ และการตอบโต้เหตุ","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q009","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “แผนฉุกเฉิน” ได้ถูกต้องที่สุด?","options":["การแยกของเสียตามประเภทเพื่อจัดเก็บ นำกลับใช้ หรือกำจัดอย่างเหมาะสม","แผนกำหนดบทบาท เส้นทาง การสื่อสาร และการตอบสนองเมื่อเกิดเหตุไม่ปกติ","แนวคิดเลือกมาตรการจากการกำจัดอันตรายไปจนถึงอุปกรณ์ป้องกันส่วนบุคคล","เหตุการณ์ที่ยังไม่ทำให้เกิดความสูญเสียแต่มีศักยภาพก่ออันตรายได้"],"correct_answer":"แผนกำหนดบทบาท เส้นทาง การสื่อสาร และการตอบสนองเมื่อเกิดเหตุไม่ปกติ","explanation":"แผนฉุกเฉิน หมายถึง แผนกำหนดบทบาท เส้นทาง การสื่อสาร และการตอบสนองเมื่อเกิดเหตุไม่ปกติ","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q010","subject_code":"20001-1001","prompt":"ข้อใดอธิบายความหมายของ “เหตุเกือบเกิด” ได้ถูกต้องที่สุด?","options":["การออกแบบงาน เครื่องมือ และท่าทางให้เหมาะกับความสามารถของมนุษย์","กระบวนการระบุอันตราย วิเคราะห์ความเสี่ยง และกำหนดมาตรการควบคุม","เหตุการณ์ที่ยังไม่ทำให้เกิดความสูญเสียแต่มีศักยภาพก่ออันตรายได้","ค่านิยมและพฤติกรรมร่วมที่ให้ความสำคัญกับความปลอดภัยในทุกระดับ"],"correct_answer":"เหตุการณ์ที่ยังไม่ทำให้เกิดความสูญเสียแต่มีศักยภาพก่ออันตรายได้","explanation":"เหตุเกือบเกิด หมายถึง เหตุการณ์ที่ยังไม่ทำให้เกิดความสูญเสียแต่มีศักยภาพก่ออันตรายได้","difficulty":"basic","theme":"safety"},{"source_key":"20001-1001-q011","subject_code":"20001-1001","prompt":"หากต้องการตัดสินใจเลือกมาตรการที่เหมาะกับงาน แนวทางใดเหมาะสมที่สุด?","options":["เลือกใช้ ความเสี่ยง เพื่อจัดลำดับประเด็นที่ควรควบคุมก่อนหลัง","เลือกใช้ การประเมินความเสี่ยง เพื่อตัดสินใจเลือกมาตรการที่เหมาะกับงาน","เลือกใช้ อันตราย เพื่อระบุสิ่งที่อาจก่ออันตรายก่อนเริ่มงาน","เลือกใช้ เหตุเกือบเกิด เพื่อค้นหาสัญญาณเตือนก่อนเกิดอุบัติเหตุจริง"],"correct_answer":"เลือกใช้ การประเมินความเสี่ยง เพื่อตัดสินใจเลือกมาตรการที่เหมาะกับงาน","explanation":"ควรเลือก การประเมินความเสี่ยง เพราะใช้เพื่อตัดสินใจเลือกมาตรการที่เหมาะกับงาน","difficulty":"easy","theme":"safety"},{"source_key":"20001-1001-q012","subject_code":"20001-1001","prompt":"หากต้องการลดการพึ่งพาพฤติกรรมบุคคลในการควบคุมอันตราย แนวทางใดเหมาะสมที่สุด?","options":["เลือกใช้ การควบคุมทางวิศวกรรม เพื่อลดการสัมผัสโดยปรับสภาพแวดล้อมหรือเครื่องจักร","เลือกใช้ SDS เพื่อค้นหาวิธีจัดการสารเคมีอย่างปลอดภัยก่อนใช้งาน","เลือกใช้ การคัดแยกของเสีย เพื่อลดการปะปนและเพิ่มประสิทธิภาพการจัดการของเสีย","เลือกใช้ ลำดับชั้นการควบคุม เพื่อลดการพึ่งพาพฤติกรรมบุคคลในการควบคุมอันตราย"],"correct_answer":"เลือกใช้ ลำดับชั้นการควบคุม เพื่อลดการพึ่งพาพฤติกรรมบุคคลในการควบคุมอันตราย","explanation":"ควรเลือก ลำดับชั้นการควบคุม เพราะใช้เพื่อลดการพึ่งพาพฤติกรรมบุคคลในการควบคุมอันตราย","difficulty":"easy","theme":"safety"},{"source_key":"20001-1001-q013","subject_code":"20001-1001","prompt":"หากต้องการลดการสัมผัสโดยปรับสภาพแวดล้อมหรือเครื่องจักร แนวทางใดเหมาะสมที่สุด?","options":["เลือกใช้ SDS เพื่อค้นหาวิธีจัดการสารเคมีอย่างปลอดภัยก่อนใช้งาน","เลือกใช้ การควบคุมทางวิศวกรรม เพื่อลดการสัมผัสโดยปรับสภาพแวดล้อมหร